insert into interaction_rules(generics,level,hi,bn,mr) values(ARRAY['paracetamol','paracetamol'],'danger','Dolo + Crocin dono Paracetamol hain — overdose se liver kharab. Ek lo, doctor se poochho.','Dolo + Crocin dutoi Paracetamol — overdose e liver kharap.','Dolo + Crocin donhi Paracetamol — overdose ne liver kharab. Ekach ghya.');
insert into interaction_rules(generics,level,hi,bn,mr) values(ARRAY['ibuprofen','aspirin'],'danger','Brufen + Ecosprin saath me pet me khoon ka khatra. Doctor ke bina mat lo.','Brufen + Ecosprin eksathe pet e rokto jhorte pare.','Brufen + Ecosprin ekatra potat raktasravacha dhoka.');
insert into interaction_rules(generics,level,hi,bn,mr) values(ARRAY['ibuprofen','losartan'],'warn','Dard ki dawai BP dawai ka asar kam karti hai + kidney load. 3 din se zyada to doctor.','Byathar osudh BP osudher kaj komay.','Dukhichi goli BP golicha parinam kami karte.');
insert into interaction_rules(generics,level,hi,bn,mr) values(ARRAY['ibuprofen','telmisartan'],'warn','Dard ki dawai BP dawai ka asar kam karti hai. Doctor ko batao.','Byathar osudh BP osudher kaj komay.','Dukhichi goli BP golicha parinam kami karte.');
insert into interaction_rules(generics,level,hi,bn,mr) values(ARRAY['metformin','metronidazole'],'warn','Sugar + infection dawai saath me — sharab bilkul nahi, sugar check karo.','Sugar + infection osudh — mod noy.','Sakhar + sansarg goli — daru naka.');
insert into interaction_rules(generics,level,hi,bn,mr) values(ARRAY['ciprofloxacin','antacid'],'warn','Cifran antacid/doodh ke saath kaam nahi karegi. 2 ghante ka gap rakho.','Cifran antacid/dudh sathe kaj korbe na. 2 ghonta gap.','Cifran antacid/dudhasobat kam karnar nahi. 2 tas gap theva.');
insert into interaction_rules(generics,level,hi,bn,mr) values(ARRAY['ciprofloxacin','iron-folic'],'warn','Cifran iron ke saath mat lo — 2 ghante gap.','Cifran iron sathe noy — 2 ghonta gap.','Cifran lohasobat naka — 2 tas gap.');
insert into interaction_rules(generics,level,hi,bn,mr) values(ARRAY['levothyroxine','iron-folic'],'warn','Thyroid + iron ek saath mat lo — 4 ghante gap, thyroid subah khali pet.','Thyroid + iron eksathe noy — 4 ghonta gap.','Thyroid + loh ekatra naka — 4 tas gap.');
insert into interaction_rules(generics,level,hi,bn,mr) values(ARRAY['levothyroxine','calcium'],'warn','Thyroid + calcium ek saath mat lo — 4 ghante gap.','Thyroid + calcium eksathe noy.','Thyroid + calcium ekatra naka.');
insert into interaction_rules(generics,level,hi,bn,mr) values(ARRAY['atenolol','salbutamol-inhaler'],'warn','Ye BP dawai dame ke inhaler ka asar kam kar sakti hai. Doctor ko batao.','Ei BP osudh inhaler er kaj komate pare.','Hi BP goli inhalercha parinam kami karu shakte.');
insert into interaction_rules(generics,level,hi,bn,mr) values(ARRAY['prednisolone','metformin'],'warn','Steroid sugar badhata hai — sugar roz check karo, doctor ko batao.','Steroid sugar baray — roj check.','Steroid sakhar vadhavte — roz tapaasa.');
insert into interaction_rules(generics,level,hi,bn,mr) values(ARRAY['aspirin','ibuprofen'],'danger','Do khoon-patla/dard dawai saath me — pet se khoon ka khatra.','Duto osudh eksathe — rokto jhorar bhoy.','Don golya ekatra — raktasravacha dhoka.');
